          '道光十八年（1838），御前爆发大辩论：太常寺少卿许乃济主张弛禁，干脆准许内地种烟征税；鸿胪寺卿黄爵滋针锋相对，主张重治吸食、逾期处死。时任湖广总督的林则徐上奏力挺严禁，其中一句后来传遍天下：「若犹泄泄视之，是使数十年后，中原几无可以御敌之兵，且无可以充饷之银。」道光帝被这句话击中，连日召对，年底任命林则徐为钦差大臣，驰赴广东查办海口。',
