          '4 月 6 日起，炮击昼夜不停。巨炮每次轰鸣，城墙就塌下一角，守军夜里用木桩、土袋和湿皮革把缺口重新补上——白天塌、夜里修，仗打成了泥瓦匠的加班。海上，拜占庭用铁链锁死金角湾入口，舰队进不来；穆罕默德随后做出整场围城最惊人的一步：把约七十艘战船涂油垫木，一夜之间从加拉塔后方的陆地翻过山丘，硬生生拖进了金角湾。城防的逻辑，从这一夜开始崩塌。',
