          '旧大陆送去的不只是人，而是一整支生物侵略军：猪、牛、马、羊、小麦、甘蔗，以及天花、麻疹、流感、斑疹伤寒。美洲人一万多年未曾接触这些病原，免疫系统一片空白；1518 年前后天花在中部美洲大流行，直接为科尔特斯的几百名士兵开了城门。',
          '人口代价是灾难级的：学界估计，一个世纪内美洲原住民人口损失约九成——从数千万级跌到数百万级。阿兹特克与印加帝国的陷落，一半靠枪炮与阴谋，另一半靠病毒：皮萨罗用一百六十八人俘虏了拥兵数百万的印加皇帝，数学上最合理的解释不在武器里，而在他的士兵早已把天花带到了之前的沿海。',
