          '1648 年《威斯特伐利亚和约》收官：加尔文派获得承认，「教随国定」固化为制度，国家利益正式高于教派立场——欧洲打累了，发明了现代主权体系来给宗教战争收尾。此后的国际秩序底座上，刻着这场战争的全部疲惫。',
          '心理代价同样真实：被教义互相处决了几代之后，欧洲人对「为信仰杀人」这件事产生了深入骨髓的集体性恐惧——神学家此后开口都要先掂量血债。这份恐惧是启蒙时代宗教宽容最重要的心理土壤。宽容从来不是靠想通了才有的，很大程度上，是打怕了才有的；而打怕之后的反思，也是反思。',
