          '核时代是最后的转折：1945 年 7 月 16 日「三位一体」核试验成功，数年内苏、英、法、中相继拥核，「相互确保摧毁」反而冻结了大国间的直接热战。核威慑是最昂贵的和平：七千万条生命换来的教训加上同归于尽的概率表，把「再也不能这样打」从愿望变成了算术。',
