          '甘地为平息加尔各答的仇杀绝食至几乎丧命，1948 年 1 月被一名印度教极端分子刺杀——独立之父死在独立的第一个冬天。真纳同年死于肺结核，没来得及给新国家立好规矩。两个国家的开国一代，都被分治的账单压垮了健康。',
