          '胡夫继承父亲斯尼夫鲁的事业——后者已经连修三座金字塔（一座中途坍塌、一座被迫更改坡度），到胡夫这一代，国家的组织力与工程经验都到了顶格。尼罗河的馈赠是前提：洪水季农田休耕，正好释放出全国劳动力，粮仓与运河都是现成的——工程等于把「农闲」变成了「国建」。',
