          '它还反哺了出发地与第三国：汉译佛典保存了大量梵语原本已佚的经典，成为世界佛学研究的基础文本；佛教经中国传入朝鲜、日本与越南——东亚「汉字—儒家—佛教」三大件就此配齐。一个梦引发的三千里西行，最终把整个东亚的精神地图重新画过。',
