          '哈里发马蒙（813—833 在位）的动机兼有信仰与好胜：他扶植的学派相信理性是通向神的方法，希腊哲学正是工具；他把「智慧宫」扩建成皇家译场与图书馆，还派人赴拜占庭搜购希腊手稿——买不到就换，换不到就借。10 世纪书目《目录之书》记下他著名的梦：梦中亚里士多德应许与他论道，哲人答他——合乎理性者即为善。',
