          '辩论不靠嗓门靠论辩术。齐国设稷下学宫，据载「不治而议论」，诸子皆可登台；孟轲与告子辩人性，纵横家张仪苏秦靠一张嘴重构六国结盟。用言辞而非血缘决定政策，这在世界史的同期都属于激进实验。稷下先生领俸不任政务，只出思想——这份待遇，后世再也没能复制。',
