          '前 213 年焚书、挟书律令，把辩论场的门焊死了半扇。此后两千年的思想史，多是这五百年遗产的内部回响：魏晋清谈拾起老庄，宋明理学重铸儒学。开放的辩论再未以同样规模重现。先有焚书的火，后有独尊的俸禄——权力换了个姿势，做了同一件事。',
