          '区别在那一问。黑纸包着的管子通电，附近的荧光屏亮了：他换位置、换距离、加遮挡，亮度随距离变化；射线穿透纸、木头、薄金属片，却不被磁场偏转——它不是已知的阴极射线。伦琴给它起名 X：因为未知。顺手翻过的问题，他偏偏停下来做了六周系统实验。',
