          '反对的力量来自体制边缘：萨摩、长州等外样大名（德川家康当年夺天下的失败者们）与饱受经济窘迫的下级武士。「尊王攘夷」起初是排外口号，挨过萨英战争与下关炮击的毒打后，萨长武士迅速改弦——攘夷不可行，唯有开国自强。目标从排外转向倒幕。',
