          '接着是对武士阶级的清算：1872 年颁布学制、1873 年颁布征兵令，平民可以且必须当兵、上学；1876 年秩禄处分将武士俸禄折价一次性买断，同年颁布废刀令——佩刀的权利连同这个阶级的经济基础一起取消。旧武士反弹，西乡隆盛率萨摩士族发动西南战争（1877），被一支由农家子弟组成的征兵军镇压。最有讽刺意味的一幕：消灭武士的战争，恰恰证明没有武士也行。',
          '为什么旧阶级拆得掉？因为新政府不是单一集团的私利，而是下层武士、公卿与豪商的联盟，他们在旧体制里本就一无所有。革命最彻底的地方，往往是既得利益最少的地方。',
