          '路径清晰：先办国营示范工厂（纺织、造船、矿山），再低价转让给三井、三菱等政商，扶植私人财阀接管产业；1872 年新桥至横滨铁路通车，电信、银行、统一货币次第铺开；《学制》把义务教育铺向全国——「邑无不学之户，家无不学之人」。这一切的经费，很大一部分来自无赔偿的地税改革。',
