          '代价同样真实：政府把巨额战争赔款投入扩军，军部在胜利中坐大；农民与纺织女工撑起出口，工时与工资惨不忍睹；1905 年朴茨茅斯和约未获赔款，东京民众烧毁报纸与警署（日比谷烧打事件）——对外胜利与对内贫困、政治狂热之间的裂缝，明治末年已经清晰可见。',
