          '这场活动同时是电视史的巅峰：全球约六亿人收看直播——当时地球上每三个人就有一个在看。人类第一次实时共同见证同一件事，而且见证的是自己的同类站在另一个天体上。直播的信号从月球出发，经澳大利亚与加州的深空天线，转播进各国的客厅。',
          '一个月岩都没带回来的另一项遗产同样深刻：从月球回望，「地出」（1968 年阿波罗 8 号拍摄）与「蓝色弹珠」（1972 年阿波罗 17 号拍摄）第一次让人类看见家园的整体——一个没有国界线的蓝色球体。这两张照片成了环保运动的图腾，1970 年第一个地球日紧随其后。',
