          '但引爆的原料已经齐备：3G 网络在多国铺开，带宽终于跑得动网页与图片；电容多点触控技术成熟，成本降到消费级；ARM 芯片的能效足以驱动一台真正的操作系统；WiFi 让调试与下载不再痛苦。缺的不是零件，是把零件组装成一个「放进口袋的电脑」的决定。',
          '乔布斯的决定是反常规的：iPhone 的内核是缩水版的 Mac OS X，电话功能反而只是其中一个「应用」。这个排序定义了此后的一切——手机不再是设备，是平台。',
