          '1598 年 9 月 18 日，丰臣秀吉病死伏见城，遗令撤军。撤退路上的露梁海战成了最后一幕：11 月 19 日凌晨，中朝联军在露梁海峡截击回撤日军，年逾七十的明将邓子龙与李舜臣前后夹击，火光把海峡照成白昼——两位主帅都在这一夜战死，李舜臣中弹前留下的遗言是「战方急，慎勿言我死」。',
          '账单摆在三国面前：朝鲜国土化为焦土，三都尽毁，人口锐减、典籍农器焚掠一空，士林柳成龙战后写《惩毖录》痛定思痛；明朝太仓库为这场「万历三大征」之一掏出七八百万两白银，财政的窟窿直接加速了帝国的衰亡；日本十万远征军葬身异国，丰臣政权因战争透支元气，两年后关原一战易主。',
          '还有一个隐蔽的受益者：明军精锐与辽东饷银被朝鲜战场吸干，建州的努尔哈赤在无人盯防的东北悄悄壮大——二十年后萨尔浒一战，后金崛起，东亚的天平换了支点。打败日本的那场战争，顺手给下一个征服者让了路。',
