          '朝鲜把这场战争刻进了国族身份：全国立祠祭祀「忠武公」李舜臣，光化门广场铜像至今是首尔地标；对明朝的救命之恩，朝鲜修大报坛世代感念，「小中华」的自认在战后愈加深厚——这份情义与执念，塑造了此后三百年朝鲜的内外姿态。',
          '故事活着还有另一条路径：龟船被写进教科书与游戏，2014 年电影《鸣梁海战》刷新韩国影史观影纪录。七年的战争，两国各自消化了四百年——朝鲜记住的是一个将军，日本记住的是一个教训，中国记住的则是一笔再也补不上的军费。',
