          '此后两百年胜负手轮转：1144年埃德萨陷落，第二次东征无功而返；1187年萨拉丁在哈丁角全歼十字军主力，收复耶路撒冷；第三次东征，狮心王理查三度逼近圣城而不得，最终与萨拉丁签约——基督徒获准朝圣。最重的一记背刺来自自己人：1204年第四次东征为债务与内讧掉头攻陷君士坦丁堡，拜占庭被洗劫，东西教会结下死仇。',
