          '更持久的战利品是书：欧洲人从阿拉伯世界带回亚里士多德的完整文本、阿拉伯数字与医学天文著作，12世纪的翻译运动随之兴起。十字军的剑没能打开圣城，商队与抄工却悄悄打开了另一扇门。',
