          '但先例的威力超出所有人预期：既然王权可以被条文约束一次，就可以被约束第二次。1225年重颁版与税收授权挂钩——「无同意不纳税」的议会逻辑从此有了文本抓手，13世纪末英格兰议会成型，用的正是这份语法。',
