          '1948年《世界人权宣言》的起草者同样引它为源头之一。今天全世界现存的大宪章原件只有四份：大英图书馆藏两份，林肯与索尔兹伯里大教堂各藏一份——1215年那场失败谈判的遗物，被当作宪政文明的圣物陈列。',
