          '晚上十点后，成千上万人涌向检查站。边防军没有接到开枪或放行的指令，请示电话打上去无人拍板。波恩霍尔默街检查站的军官耶格面对越聚越多的人群，在反复请示无果后，自己做了决定：23 时 30 分，放下栏杆，放行。铁幕不靠轰炸摧毁，靠的是链条上某个人不再拉紧它。',
