          '但三十年后再看，这个道理需要修正：墙倒了，历史没有终结。统一的德国成为欧洲的引擎，欧洲却迎来民粹回潮；福山宣布终点的历史，在 2014 年乌克兰、2022 年俄乌战争里重新排开阵型。冷战后的乐观，成了它自己的年代错位。',
