          '闸门从边缘打开。1989 年，东欧各国政权在苏联「不干预」的默许下接连倒台：波兰圆桌谈判、匈牙利开放边境、柏林墙倒塌。1990 年 3 月，立陶宛率先宣布独立，莫斯科用经济封锁与武装威慑都按不住。1991 年 3 月的全联盟公投中，约四分之三投票者赞成保留联盟——但公投挡不住各共和国的独立浪潮。',
