          '叶利钦跳上白宫（俄罗斯议会大厦）前的坦克，宣读声明，宣布政变非法，号召总罢工。数万市民围住白宫筑起人墙，电视台与电台被反对者抢占，部分军队倒戈，三名市民在隧道冲突中身亡。8 月 21 日，政变崩溃，戈尔巴乔夫被送回莫斯科——名义上官复原职，实际上权力已经易手：保守派被一网打尽，叶利钦成了真正的实权人物。',
          '政变摧毁的是联盟存在的最后黏合剂。此后各共和国竞相宣布独立，苏联共产党被停止活动；12 月 1 日乌克兰公投，九成投票者赞成独立。12 月 8 日，俄罗斯、乌克兰、白俄罗斯三国领导人在别洛韦日森林的猎别墅里签署协议，宣布苏联「停止存在」。12 月 21 日，十一国在阿拉木图加入；12 月 25 日晚，戈尔巴乔夫辞去苏联总统，红旗降下。',
