          '2003 年的伊拉克战争把账单翻倍。开战理由中的大规模杀伤性武器与基地组织关联，事后均被证伪——伊拉克战争与九一一并无实质因果，却在同一面「反恐」大旗下开打。据布朗大学「战争成本」项目估算，美国的反恐战争累计耗资约八万亿美元，直接造成的死亡以数十万计，美军自身阵亡逾七千人。',
          '国内的代价以另一种方式支付：2002 年成立国土安全部（合并二十二个机构），《爱国者法案》扩张监控权限，机场安检成为全球的日常仪式。安全与自由的天平，从那天起被永久重新定价；对穆斯林群体的怀疑与偏见，也成为西方社会一道至今未愈的裂痕。',
