          '各国的路线很快分化：中国推行「动态清零」，以封控、核酸与健康码追踪病毒；多数西方国家在封锁与重启之间反复摇摆，瑞典一度选择不封锁放任免疫。无论哪种路线，都验证了同一个公式：封锁越早越短，代价越小——迟疑的成本以周计。',
          '科学的反击以历史最快速度展开：mRNA 疫苗从拿到基因序列到获批使用只用了约十一个月，此前人类疫苗研发的最快纪录是四年；2020 年 12 月起多款疫苗陆续投入使用。2021 年底出现的奥密克戎变异株传播力更强、致病力相对下降，大流行在疫苗与自然感染的双重屏障下，逐渐转为地方性流行。',
