          '地缘与制度的账单在事后陆续送达：全球供应链开始「去风险」重组，芯片、医药等命脉产业回流或友岸外包；中美互信进一步下滑，病毒起源的争论至今没有定论（美国情报界的评估始终分裂）；世卫组织开启《大流行协定》谈判，试图为下一次补课。',
