          '围棋不同：十九路棋盘的状态空间超过十的一百七十次方，宇宙里的原子都不够数，蛮力彻底失效。要赢围棋，机器得像人一样有「棋感」——这恰是当时最不可能的事。所以当 2016 年 AlphaGo 四比一取胜，震撼的不只是棋界：那意味着「直觉」也能被计算。',
          '爆发另有三大燃料：GPU 算力成本十年跳水、互联网提供了海量训练数据、深度学习算法在 2012 年的 ImageNet 图像识别大赛上把错误率骤降——机器第一次「看懂」了图片。三线齐备，只差一个战场。AlphaGo 用强化学习自己跟自己下了几千万盘棋，然后来到首尔。',
