          '对奥斯曼帝国，这是扩张的顶点与心理的转折：此后苏丹的宫廷更关心多瑙河与波斯，地中海均势事实上维持，但「不可战胜」的神话第一次破了。欧洲人则收获了一份反杀的自信——奥斯曼的脚步自此未再深入西地中海。',
